<?php
class ButcheryController extends Controller
{
 public function index(){$m=$this->model('Butchery');$this->view('butchery.index',array_merge(['title'=>'Boucherie','success'=>flash('success'),'error'=>flash('error'),'siteRequired'=>!$m->hasOperationalSiteContext(),'receipts'=>$m->pendingReceipts(),'slaughters'=>$m->pendingSlaughters()],$m->dashboard()),'layouts.main');}
 public function receipt(){$this->go(function($m,$u){$m->createReceipt($_POST,$u);});}public function control($id){$this->go(function($m,$u)use($id){$m->controlReceipt($id,$_POST,$u);});}public function slaughter(){$this->go(function($m,$u){$m->createSlaughter($_POST,$u);});}public function validateSlaughter($id){$this->go(function($m,$u)use($id){$m->validateSlaughter($id,$_POST,$u);});}public function recipe(){$this->go(function($m,$u){$m->createRecipe($_POST,$u);});}public function order(){$this->go(function($m,$u){$m->createOrder($_POST,$u);});}public function results($id){$this->go(function($m,$u)use($id){$m->submitOrder($id,$_POST,$u);});}public function validateOrder($id){$this->go(function($m,$u)use($id){$m->validateOrder($id,$u);});}public function sale(){$this->go(function($m,$u){$m->sell($_POST,$u);});}public function transfer(){$this->go(function($m,$u){$m->createTransfer($_POST,$u);});}public function approveTransfer($id){$this->go(function($m,$u)use($id){$m->approveTransfer($id,$u);});}public function dispatchTransfer($id){$this->go(function($m,$u)use($id){$m->dispatchTransfer($id,$u);});}
 private function go($f){if(!verify_csrf($_POST['_token']??'')){flash('error','Session expirée.');redirect('butchery');}try{$f($this->model('Butchery'),Auth::user());flash('success','Opération boucherie enregistrée.');}catch(Exception$e){flash('error',$e->getMessage());}redirect('butchery');}
}
